(window.webpackJsonpGUI=window.webpackJsonpGUI||[]).push([[131],{1470:function(n,t,e){"use strict";e.r(t),t.default={code:"114TCPE10",title:"114-臺中市國小（競賽模式）",unlockCode:"114TCPE10",tasks:[{id:"114TCPE10-1",code:"114TCPE10-114TCPE10-1",title:"以禮相待",description:"蘇洵為避免兩個兒子蘇軾、蘇轍彼此對中發票吵架，於是訂定了他們家的規則：\n(1) 對中發票後，假如中獎金額先補貼中獎發票的花費金額。\n(2) 若還有盈餘（剩下），獎金由對中獎的人收下。\n(3) 盈餘的金額假如大於 200，要對手足以禮相待，分享 100 元。\n請輸出對中獎項的人可以拿到多少錢作為答案。",examples:[{input:"10\n500",output:"390 元",explanation:"先扣除花費金額 500-10=490。因為盈餘 490 大於 200，所以以禮相待，490-100=390，故輸出 390 元。"},{input:"400\n200",output:"無盈餘",explanation:"200-400=-200，沒有盈餘，故輸出無盈餘。"},{input:"100\n200",output:"100 元",explanation:"先扣除花費金額 200-100=100。因為盈餘 100 小於 200，所以直接收下獎金 100 元。"}],testCases:[{input:"10\n500",expectedOutput:"390 元",score:10},{input:"400\n200",expectedOutput:"無盈餘",score:10},{input:"100\n200",expectedOutput:"100 元",score:10},{input:"50\n250",expectedOutput:"200 元",score:10},{input:"300\n300",expectedOutput:"無盈餘",score:10}],difficulty:"L2",sb3Path:null},{id:"114TCPE10-2",code:"114TCPE10-114TCPE10-2",title:"統一發票",description:"蘇家父子三人拿著統一發票滿懷期待的兌獎，兌獎的規則如下：\n(1) 若發票號碼末 X 碼與頭獎號碼末 X 碼相同，即得對應獎項（末 8 碼＝頭獎、末 7 碼＝二獎、末 6 碼＝三獎、末 5 碼＝四獎、末 4 碼＝五獎、末 3 碼＝六獎）。若同時符合多個碼數，以碼數最長者為準。\n(2) 若發票 8 碼與特獎或特別獎號碼完全相同，即得該獎項。\n特別獎號碼：25834483。特獎號碼：46587380。頭獎號碼（三組）：41016094、98081574、07309261。\n請輸出中獎情形。",examples:[{input:"47887495",output:"無中獎",explanation:"號碼末幾碼都沒有跟任何頭獎號碼相同。"},{input:"451232",output:"非統一編號",explanation:"輸入只有 6 碼，不符合 8 碼發票的規範。"},{input:"25834483",output:"特別獎",explanation:"與特別獎號碼完全相同。"}],testCases:[{input:"47887495",expectedOutput:"無中獎",score:10},{input:"451232",expectedOutput:"非統一編號",score:10},{input:"25834483",expectedOutput:"特別獎",score:10},{input:"46587380",expectedOutput:"特獎",score:10},{input:"41016094",expectedOutput:"頭獎",score:10},{input:"00007261",expectedOutput:"六獎",score:10}],difficulty:"L3",sb3Path:null},{id:"114TCPE10-3",code:"114TCPE10-114TCPE10-3",title:"閃電十一人",description:"小明承辦了校際足球賽，需要一套自動計分與判定系統。每一場比賽只有兩隊，且只會發生兩種事情：進球 Goal、犯規 Foul。\n規則：\n進 1 球即得 1 分。\n每犯規 3 次，該隊扣 1 分。\n扣分不會讓分數低於 0 分。\n事件代碼：GA＝A隊進球、GB＝B隊進球、FA＝A隊犯規、FB＝B隊犯規。\n請依序輸出 A 隊最後得分、B 隊最後得分、比賽結果（A Win / B Win / Draw）。",examples:[{input:"7\nGA\nFA\nGA\nFB\nFB\nFB\nGB",output:"2\n0\nA Win",explanation:"A 隊：2 球、1 次犯規 → 得 2 分。B 隊：1 球、3 次犯規 → 得 1-1=0 分。"},{input:"6\nGA\nGB\nFA\nFA\nFA\nGB",output:"0\n2\nB Win",explanation:"A 隊：1 球、3 次犯規 → 得 1-1=0 分。B 隊：2 球、0 次犯規 → 得 2 分。"},{input:"4\nGA\nGB\nFA\nFB",output:"1\n1\nDraw",explanation:"A 隊：1 球、1 次犯規 → 得 1 分。B 隊：1 球、1 次犯規 → 得 1 分。"}],testCases:[{input:"7\nGA\nFA\nGA\nFB\nFB\nFB\nGB",expectedOutput:"2\n0\nA Win",score:10},{input:"6\nGA\nGB\nFA\nFA\nFA\nGB",expectedOutput:"0\n2\nB Win",score:10},{input:"4\nGA\nGB\nFA\nFB",expectedOutput:"1\n1\nDraw",score:10},{input:"9\nFA\nFA\nFA\nFA\nFA\nFA\nFA\nFA\nFA",expectedOutput:"0\n0\nDraw",score:10}],difficulty:"L3",sb3Path:null},{id:"114TCPE10-4",code:"114TCPE10-114TCPE10-4",title:"紅牌與黃牌",description:"延續閃電十一人的基本規則（進球得分、每犯規 3 次扣 1 分、分數不低於 0），新增以下規則：\n每犯規 2 次，該隊得 1 張黃牌。\n同一隊累積 2 張黃牌，自動轉為 1 張紅牌。\n一旦出現紅牌，該隊立刻再扣 1 分（紅牌只會影響一次，不會重複扣分）。\n請依序輸出 A 隊最後得分、B 隊最後得分、比賽結果（A Win / B Win / Draw）。",examples:[{input:"6\nGA\nFA\nFA\nFA\nFA\nGB",output:"0\n1\nB Win",explanation:"A 隊：1 球 →+1；4 次犯規 → 扣 1 分；2 黃牌 → 1 紅牌 → 再扣 1 分；總分 1-1-1，扣到 0 為止。B 隊：1 球 → 1 分。"},{input:"5\nGA\nFA\nFA\nGB\nFB",output:"1\n1\nDraw",explanation:"A 隊：1 球 →+1；2 次犯規 → 1 張黃牌（不扣分）；總分 1。B 隊：1 球 →+1；1 次犯規 → 無事發生；總分 1。"},{input:"8\nGA\nGA\nFA\nFA\nFA\nFA\nGB\nGB",output:"0\n2\nB Win",explanation:"A 隊：2 球 →+2；4 次犯規 → 扣 1 分；2 黃牌 → 1 紅牌 → 再扣 1 分；總分扣到 0 為止。B 隊：2 球 → 2 分、0 犯規。"}],testCases:[{input:"6\nGA\nFA\nFA\nFA\nFA\nGB",expectedOutput:"0\n1\nB Win",score:10},{input:"5\nGA\nFA\nFA\nGB\nFB",expectedOutput:"1\n1\nDraw",score:10},{input:"8\nGA\nGA\nFA\nFA\nFA\nFA\nGB\nGB",expectedOutput:"0\n2\nB Win",score:10},{input:"9\nFA\nFA\nFA\nFA\nFA\nFA\nFA\nFA\nFA",expectedOutput:"0\n0\nDraw",score:10}],difficulty:"L4",sb3Path:null},{id:"114TCPE10-5",code:"114TCPE10-114TCPE10-5",title:"提前結束",description:"延續紅牌與黃牌的規則，新增以下規則：\n任一隊出現 1 張紅牌，比賽立刻結束，後續事件全部忽略，輸出結果以「結束當下」為準。\n請依序輸出 A 隊最後得分、B 隊最後得分、比賽結果（A Win / B Win / Draw）。",examples:[{input:"7\nGA\nFA\nFA\nFA\nGB\nFA\nGB",output:"0\n1\nB Win",explanation:"第 6 個事件（FA）讓 A 隊出現紅牌，比賽立刻結束，最後一個 GB 不計。"},{input:"6\nGB\nFB\nFB\nFB\nFB\nGA",output:"0\n0\nDraw",explanation:"第 5 個事件（FB）讓 B 隊出現紅牌，比賽立刻結束，最後的 GA 不計。"},{input:"8\nGA\nGA\nFA\nFA\nFA\nFA\nGB\nGB",output:"0\n0\nDraw",explanation:"第 6 個事件（FA）讓 A 隊出現紅牌，比賽立刻結束，兩個 GB 都不計。"}],testCases:[{input:"7\nGA\nFA\nFA\nFA\nGB\nFA\nGB",expectedOutput:"0\n1\nB Win",score:10},{input:"6\nGB\nFB\nFB\nFB\nFB\nGA",expectedOutput:"0\n0\nDraw",score:10},{input:"8\nGA\nGA\nFA\nFA\nFA\nFA\nGB\nGB",expectedOutput:"0\n0\nDraw",score:10},{input:"5\nGA\nGB\nFA\nGB\nGA",expectedOutput:"2\n2\nDraw",score:10}],difficulty:"L4",sb3Path:null}]}}}]);